-- Критериите от директора (последния раздел) се променят от „Оценяване → Карти“.
insert into public.eval_templates (code, kind, grp, name, title, adopted, col_label, roles, criteria, base, total, guide, sort) values
('attest_speech', 'attest', 'ped', 'Атестиране — логопед (Прил. № 22)', 'АТЕСТАЦИОННА КАРТА НА РЕХАБИЛИТАТОР НА СЛУХА И ГОВОРА, ТРЕНЬОР ПО ВИД СПОРТ, КОРЕПЕТИТОР, ХОРЕОГРАФ, ЛОГОПЕД, РЪКОВОДИТЕЛ НА НАПРАВЛЕНИЕ ИНФОРМАЦИОННИ И КОМУНИКАЦИОННИ ТЕХНОЛОГИИ',
 'Приложение № 22 към чл. 82, ал. 1, т. 3', 'Б. Области на компетентност и критерии по тях', '{speech_therapist}',
 '[{"n": "I.1", "h": "I. Педагогически компетентности: планиране, преподаване, оценяване и управление на класа/групата", "g": "Планиране", "max": 6, "items": [{"k": "I.1.1", "t": "Залага ясни и конкретни цели при планирането на дейността и предвижда възможност за преструктуриране и промяна на годишното планиране – при необходимост.", "max": 2}, {"k": "I.1.2", "t": "Планира дейности за обща и допълнителна подкрепа за личностното развитие на децата/учениците.", "max": 2}, {"k": "I.1.3", "t": "Планира иновативни методи и подходящ инструментариум за оценка и превенция на обучителни затруднения и за формиране на социални умения.", "max": 2}]}, {"n": "I.2", "h": "I. Педагогически компетентности: планиране, преподаване, оценяване и управление на класа/групата", "g": "Организиране, управление и координация на образователния процес", "max": 8, "items": [{"k": "I.2.1", "t": "Проследява напредъка в развитието на децата/учениците с цел постигане на планираните резултати в съответствие с потребностите, способностите и интересите им и формираните ключови компетентности.", "max": 2}, {"k": "I.2.2", "t": "Използва ефективно иновативни и интерактивни методи за индивидуална и групова работа, като формира и развива основни социални умения. Прилага компетентностния подход в работата си при придобиване на ключови компетентности от децата/учениците съгласно чл. 77, ал. 1 от ЗПУО.", "max": 2}, {"k": "I.2.3", "t": "Подбира и прилага подходящи методи, средства и дидактически материали за реализиране на поставените цели, включително създадени от самия него.", "max": 2}, {"k": "I.2.4", "t": "Спазва и контролира спазването на книжовноезиковите норми на българския език в процеса на обучение, възпитание и социализация на децата и учениците.", "max": 2}]}, {"n": "I.3", "h": "I. Педагогически компетентности: планиране, преподаване, оценяване и управление на класа/групата", "g": "Оценяване напредъка на деца/ученици", "max": 6, "items": [{"k": "I.3.1", "t": "Използва подходящи методи и форми за проверка и оценка (диагностика) на постигнатите от децата/учениците индивидуални/групови резултати.", "max": 2}, {"k": "I.3.2", "t": "Проследява и анализира постигнатите резултати, като осигурява обща и/или допълнителна подкрепа за личностно развитие.", "max": 2}, {"k": "I.3.3", "t": "Информира родителите за постигнатите резултати; дефинира цели и мерки за подкрепа на база индивидуалния напредък на детето/ученика.", "max": 2}]}, {"n": "I.4", "h": "I. Педагогически компетентности: планиране, преподаване, оценяване и управление на класа/групата", "g": "Управление на групата/класа", "max": 4, "items": [{"k": "I.4.1", "t": "Ръководи групата или работи индивидуално с дете/ученик в съответствие с етичния кодекс на училищната общност.", "max": 2}, {"k": "I.4.2", "t": "Осигурява сигурна и подходяща физическа, психологическа и социална среда за подкрепа и развитие на децата и учениците и формира отношения на загриженост и ефективна комуникация между всички участници в образователния процес.", "max": 2}]}, {"n": "II", "g": "II. Социална и гражданска компетентност: работа с участниците в образователния процес, работа със заинтересовани страни (родители, социални партньори, бизнес и др.), участие във формирането на образователни политики и в изпълнението на дейностите по тях", "max": 10, "items": [{"k": "II.1", "t": "Участва в разработването и изпълнението на стратегията на институцията и спомага за нейното актуализиране.", "max": 2}, {"k": "II.2.1", "t": "Има изградени ефективни професионални взаимоотношения с участниците в образователния процес в институцията и всички заинтересовани страни, като взема активно участие в работата на педагогическия съвет, екипи и комисии, методически обединения; участва в работа по проекти и програми.", "max": 2}, {"k": "II.2.2", "t": "Активно участва в организирането и провеждането на извънурочни и извънкласни форми на обучение.", "max": 2}, {"k": "II.2.3", "t": "Взаимодейства активно за приобщаване на родителите в образователния процес и е диалогичен с родителската общност.", "max": 2}, {"k": "II.3", "t": "Осъществява методическа и организационна подкрепа на новоназначени педагогически специалисти. Участва в дейността на национални, областни, общински комисии, свързани с разработване и изпълнение на основни образователни политики или проекти.", "max": 2}]}, {"n": "III", "g": "III. Други професионални изисквания за изпълнение на длъжността", "max": 6, "items": [{"k": "III.1", "t": "Оценява професионалното си развитие, както и необходимостта от повишаване на квалификацията си по теми, свързани с приоритетите на институцията, и има задължителните квалификационни кредити.", "max": 2}, {"k": "III.2", "t": "Професионално изпълнява задълженията си съгласно длъжностната характеристика и участва във форми на квалификация.", "max": 2}, {"k": "III.3", "t": "Познава и прилага нормативната уредба в системата на предучилищното и училищното образование, учебната документация и документите на институцията.", "max": 2}]}, {"n": "IV", "g": "IV. Критерии, определени от директора на институцията", "max": 10, "items": [{"k": "IV.1", "t": "Прилага информационни и комуникационни технологии в логопедичната практика, като използва специализиран софтуер, електронни ресурси и интерактивни материали за развитие на комуникативните и езиковите умения на децата и учениците. Разработва и прилага собствени електронни логопедични материали.", "max": 2}, {"k": "IV.2", "t": "Осъществява ефективно взаимодействие с педагогическите специалисти, родителите и специалистите от ЕПЛР, като участва активно в екипната работа за осигуряване на цялостна подкрепа на детето или ученика. Допринася за създаване на позитивен организационен климат и добра професионална комуникация.", "max": 2}, {"k": "IV.3", "t": "Планира, организира и провежда качествено логопедичната дейност, като води изискуемата документация точно, коректно и в срок. Изпълнява поставените задачи и спазва вътрешните правила, графици и нормативни изисквания.", "max": 2}, {"k": "IV.4", "t": "Прилага съвременни методи и подходи за диагностика, терапия и развитие на комуникативните умения, съобразени с индивидуалните потребности на децата и учениците. Насърчава активното участие, самостоятелността и увереността им в процеса на комуникация.", "max": 2}, {"k": "IV.5", "t": "Повишава професионалната си квалификация и прилага придобитите знания в практиката. Актуализира и усъвършенства професионалните си компетентности чрез прилагане на съвременни подходи за превенция, оценка и терапия на комуникативните нарушения.", "max": 2}]}]', null, 50,
 'Скала за определяне на достигнатата степен на изпълнение на критериите по областите на професионална компетентност
Педагогически компетентности: планиране, преподаване, оценяване и управление на класа/групата
1,0 точка: Професионалните знания и умения имат необходимост от подобрение, съответстващо на длъжността. Трудно се ориентира в поставените задачи, което затруднява планирането и организирането на работата. Непоследователен при планирането на задачите, несъобразяване с целите. Затруднява се при структурирането на информацията. Трудности при формулирането на реалистични и ясни цели и при диференцирането на задачите за индивидуална и групова работа. Затруднение при използването на иновативни и интерактивни методи и на информационни и комуникационни технологии в работата си. Оценяването/диагностицирането на резултатите е формално и немотивиращо. Липсва заинтересованост към проблемите в групата/класа. Нуждае се от допълнителни инструкции и обяснения за изясняване на задълженията. Необходима е допълнителна квалификация и подкрепа.
1,5 точки: Има необходимите знания и може да се справя с възникналите трудности. Планира работата си и ориентира дейността си към постигане на очакваните резултати. Надгражда знанията, уменията и отношенията в различните области на компетентност. Планира и използва оценяването/диагностицирането за проследяване на напредъка и за установяване на нуждите от подкрепа. Изпълнява планираните дейности и търси подкрепа. Използва информационни и комуникационни технологии в работата си. Умее да работи индивидуално и групово с децата/учениците. Необходима е допълнителна квалификация.
2,0 точки: Има висока професионална компетентност, задълбочено познава естеството на извършваната работа. Следи новостите в своята област. Успешно планира и организира собствената работа в рамките на основните и допълнителните форми на работа. Постига очакваните резултати. Оценява или диагностицира, за да измери постигнат резултат. Дава обратна връзка и насока за подобрение. Използва индивидуален подход. Справя се с проблеми в работата с деца със СОП, с обучителни трудности, от уязвими общности и др. Бързо се ориентира в конкретна ситуация и допринася за успешно решение. Ефективно прилага иновативни и интерактивни методи на обучение, ориентирани към напредъка на всяко дете/ученик. Умее да мотивира децата/учениците за работа в екип. Оказва методическа и организационна подкрепа.
Социална и гражданска компетентност: работа с участниците в образователния процес, работа със заинтересовани страни (родители, социални партньори, бизнес и др.), участие във формирането на образователни политики и в изпълнението на дейностите по тях
1,0 точка: Трудно работи с колегите; не изразява готовност да сътрудничи. Има проблеми при работа в екип. Среща трудности при справянето с конфликтни ситуации и вземането на добри решения. Пасивен, работи без желание само върху задачи, които са изрично зададени. Рядко се включва в разрешаването на проблеми, свързани със собствената работа. Няма необходимата компетентност и нагласа да помага на колегите си. Среща затруднения при работа с родителите. Не дава обратна връзка. Дейностите му не съответстват или не са обвързани със стратегията на институцията и поставените стратегически цели. Не се включва в работа по проекти. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
1,5 точки: Поддържа коректни взаимоотношения; взаимодейства с колегите си, когато е необходимо. Пълноценно общува с родителите. Проявява инициативност в работата, готовност да се включва в изпълнението на нови задачи и разрешаването на проблемни ситуации. Проявява самоинициатива, предлага решения. Включва се в подкрепа на колеги при необходимост. Препоръчва се допълнителна квалификация.
2,0 точки: Поддържа добри взаимоотношения и работи в сътрудничество с колегите и други партньори с цел изпълнение на работата. Активно взаимодейства с родителите, предлага решения и търси подкрепата им за подобряване на резултатите на децата/учениците. Насърчава както колегите си, така и родителите да дискутират, обменят идеи и да работят съвместно за разрешаването на проблеми. Отличава се с активност, дава предложения и влага усилия за подобряване процеса на работа, ангажира се с изпълнението на допълнителни задачи. Оказва методическа и организационна подкрепа.
Други професионални изисквания
1,0 точка: Спазва седмичното разписание. Среща затруднения за изпълнението, координирането и контролирането на всички планирани задачи и дейности. В екипната работа допуска закъснение и неточност, което води до слабости в изпълнението на задачите. Подценява необходимостта от повишаване на квалификацията, не я обвързва с възможностите за развитие. Няма задължителните за атестационния период брой квалификационни кредити и задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Не използва ефективно ресурсите на средата, с които институцията разполага. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
Слабо познава основните нормативни документи, които регулират системата на предучилищното и училищното образование. Слабо познава държавните образователни стандарти. Има затруднение в работата с документите на институцията. Не участва в работата по разработването и актуализирането на учебната документация. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
1,5 точки: Изпълнява своите задължения. Спазва седмичното разписание, като ефективно използва работното време. Не среща трудности при справянето с възникнали проблеми и задачи. Отнася се отговорно към работата. Проявява мотивация и участва в допълнителни обучения. Има задължителните за атестационния период брой квалификационни кредити, но няма задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Положително е настроен към предложения за промяна и обогатяване на опита. Рационално използва ресурсите на институцията. Разбира и следва образователните цели на институцията. Препоръчва се допълнителна квалификация.
Познава основните нормативни документи, които регулират системата на предучилищното и училищното образование. Познава държавните образователни стандарти. Няма трудности в работата с документите на институцията и ги оформя в срок. Участва в работни групи за разработването и актуализирането на учебната документация.
2,0 точки: Ефективно изпълнява своите задължения и отговорности. Отговорно, в срок, с необходимата точност и качествено изпълнява възложените задачи. Спазва вътрешните правила за работа. Изпълнява качествено и точно поставените задачи. Постига желаните цели в определените срокове. Преодолява възникнали трудности и информира за крайния резултат. Обогатява знанията си както чрез самоподготовка, така и чрез активното включване в организирани обучения. Има задължителните за атестационния период брой квалификационни кредити и задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Ефективно използва ресурсите/базата на институцията, обогатява ги и търси и предлага допълнителни възможности за подобряване. Изпълнява образователната политика на институцията, като подпомага колегите си при реализиране на поставените цели. Оказва методическа и организационна подкрепа.
Ефективно прилага основните нормативни документи, които регулират системата на предучилищното и училищното образование. Изпълнява задълженията си по приемане, водене, съхраняване, отчитане и унищожаване на документите, с които работи. Участва в работни групи за разработването и актуализирането на правилници, правила, планове и др. на институцията, като предлага решения за подобряване на работата. Оказва методическа и организационна подкрепа и наставничество.', 41),
('attest_psych', 'attest', 'ped', 'Атестиране — психолог (Прил. № 25)', 'АТЕСТАЦИОННА КАРТА НА ПСИХОЛОГ И ПЕДАГОГИЧЕСКИ СЪВЕТНИК',
 'Приложение № 25 към чл. 82, ал. 1, т. 6', 'Б. Области на компетентност и критерии по тях', '{psychologist}',
 '[{"n": "I.1", "h": "I. Психологически и педагогически компетентности", "g": "Планиране", "max": 6, "items": [{"k": "I.1.1", "t": "Залага конкретни цели при планирането на дейността.", "max": 2}, {"k": "I.1.2", "t": "Планира дейности за обща и допълнителна подкрепа за личностно развитие на децата/учениците.", "max": 2}, {"k": "I.1.3", "t": "Планира иновативни методи и подходящ инструментариум за оценка и превенция на обучителни затруднения и за придобиване на социални умения.", "max": 2}]}, {"n": "I.2", "h": "I. Психологически и педагогически компетентности", "g": "Организиране, управление и координации на консултативния процес", "max": 8, "items": [{"k": "I.2.1", "t": "Проследява напредъка в развитието на децата/учениците с цел постигане на планираните резултати и формираните ключови компетентности.", "max": 2}, {"k": "I.2.2", "t": "Използва ефективно иновативни и интерактивни методи за индивидуална и групова работа, като формира и развива основни социални умения.", "max": 2}, {"k": "I.2.3", "t": "Подбира и прилага подходящи методи, средства и дидактически материали за реализиране на поставените цели, включително създадени от самия него.", "max": 2}, {"k": "I.2.4", "t": "Спазва и контролира спазването на книжовноезиковите норми на българския език. Прилага компетентностния подход в работата си при придобиване на ключови компетентности от децата/учениците съгласно чл. 77, ал. 1 от ЗПУО.", "max": 2}]}, {"n": "I.3", "h": "I. Психологически и педагогически компетентности", "g": "Проследяване напредъка в развитието на деца/ученици", "max": 6, "items": [{"k": "I.3.1", "t": "Използва подходящи методи и форми за диагностика и консултиране на постигнатите от учениците индивидуални/групови резултати.", "max": 2}, {"k": "I.3.2", "t": "Проследява и анализира постигнатите резултати, като осигурява обща и/или допълнителна подкрепа за личностно развитие.", "max": 2}, {"k": "I.3.3", "t": "Информира родителите за постигнатите резултати; дефинира цели и мерки за подкрепа на база индивидуалния напредък на детето или ученика.", "max": 2}]}, {"n": "I.4", "h": "I. Психологически и педагогически компетентности", "g": "Управление на групата/класа – тренинги, групова работа с деца/ученици", "max": 4, "items": [{"k": "I.4.1", "t": "Ръководи групата или работи индивидуално с дете/ученик в съответствие с етичния кодекс на училищната общност.", "max": 2}, {"k": "I.4.2", "t": "Осигурява сигурна и подходяща физическа, психологическа и социална среда за подкрепа и развитие на децата и учениците и формира отношения на загриженост и ефективна комуникация между всички участници в образователния процес. Подпомага ученическото самоуправление.", "max": 2}]}, {"n": "II", "g": "II. Организационна компетентност: работа с участниците в образователния процес, работа със заинтересовани страни (родители, социални партньори, бизнес и др.), участие във формирането на образователни политики и в изпълнението на дейностите по тях", "max": 10, "items": [{"k": "II.1", "t": "Участва в разработването и изпълнението на стратегията на институцията и спомага за нейното актуализиране.", "max": 2}, {"k": "II.2.1", "t": "Има изградени ефективни професионални взаимоотношения с участниците в образователния процес в институцията и всички заинтересовани страни, като: взема активно участие в работата на педагогическия съвет, екипи и комисии, методически обединения; участва в работа по проекти и програми.", "max": 2}, {"k": "II.2.2", "t": "Активно участва в организирането и провеждането на извънурочни и извънкласни форми на обучение за обща и допълнителна подкрепа.", "max": 2}, {"k": "II.2.3", "t": "Взаимодейства активно за приобщаване на родителите в образователния процес и е диалогичен с родителската общност.", "max": 2}, {"k": "II.3", "t": "Работи с външни институции и партньорства. Участва в дейността на национални, областни, общински комисии, свързани с разработване и изпълнение на основни образователни политики или проекти.", "max": 2}]}, {"n": "III", "g": "III. Административна компетентност", "max": 2, "items": [{"k": "III.1", "t": "Познава и прилага нормативната уредба в системата на предучилищното и училищното образование, училищната документация и документите на институцията.", "max": 2}]}, {"n": "IV", "g": "IV. Други професионални изисквания за изпълнение на длъжността", "max": 4, "items": [{"k": "IV.1", "t": "Оценява собственото си професионално развитие, преценява необходимостта от повишаване на квалификацията си и се включва в квалификационни форми, свързани с целите на институцията или професионалната му област, и има задължителните за атестационния период брой квалификационни кредити.", "max": 2}, {"k": "IV.2", "t": "Професионално изпълнява задълженията си съгласно длъжностната характеристика и участва във форми на квалификация.", "max": 2}]}, {"n": "V", "g": "V. Критерии, определени от директора на институцията", "max": 10, "items": [{"k": "V.1", "t": "Използва информационни и комуникационни технологии в психологическата практика, включително електронни инструменти, ресурси и материали за оценяване, консултиране и развитие на социално-емоционалните компетентности на децата и учениците. Разработва и използва собствени електронни ресурси.", "max": 2}, {"k": "V.2", "t": "Работи в сътрудничество с педагогически специалисти, родители и институции, като подпомага изграждането на позитивен психологически климат и ефективна комуникация в образователната среда. Участва активно в работата на екипите за подкрепа на личностното развитие.", "max": 2}, {"k": "V.3", "t": "Планира, организира и реализира психологическата подкрепа в съответствие с потребностите на децата и учениците, като води необходимата документация коректно и в срок. Спазва вътрешните правила, работните графици и поставените от директора задачи.", "max": 2}, {"k": "V.4", "t": "Прилага ефективни методи за психологическа подкрепа, превенция и интервенция, насочени към развитие на социални, емоционални и поведенчески умения. Съдейства за създаването на безопасна, подкрепяща и приобщаваща среда и подпомага управлението на поведението на децата и учениците.", "max": 2}, {"k": "V.5", "t": "Повишава професионалната си квалификация и прилага придобитите знания в практиката. Актуализира и усъвършенства професионалните си компетентности чрез прилагане на съвременни методи и подходи за психологическа оценка, консултиране и подкрепа на децата, учениците и техните семейства.", "max": 2}]}]', null, 50,
 'Скала за определяне на достигнатата степен на изпълнение на критериите по областите на професионална компетентност
Педагогически и психологически компетентности: планиране, консултиране и управление на класа/групата и други
1,0 точка: Професионалните знания и умения имат необходимост от подобрение, съответстващо на длъжността. Трудно се ориентира в поставените задачи, което затруднява планирането и организирането на работата. Непоследователен при планирането на задачите, несъобразяване с целите. Затруднява се при структурирането на информация. Трудности при формулирането на реалистични и ясни цели и при диференцирането на задачите за индивидуална и групова работа. Затруднение при използването на иновативни и интерактивни методи и на информационни и комуникационни технологии в работата си. Оценяването/диагностицирането на резултати е формално и немотивиращо. Липсва заинтересованост към проблемите в групата/класа. Нуждае се от допълнителни инструкции и обяснения за изясняване на задълженията. Необходима е допълнителна квалификация и подкрепа.
1,5 точки: Има необходимите знания и може да се справя с възникналите трудности. Планира работата си и ориентира дейността си към постигане на очакваните резултати. Надгражда знанията, уменията и отношенията в различните области на компетентност. Планира и използва оценяването/диагностицирането за проследяване на напредъка и за установяване на нуждите от подкрепа. Изпълнява планираните дейности и търси подкрепа. Използва информационни и комуникационни технологии в работата си. Умее да работи индивидуално и групово с децата/учениците. Необходима е допълнителна квалификация.
2,0 точки: Има висока професионална компетентност, задълбочено познава естеството на извършваната работа. Следи новостите в своята област. Успешно планира и организира собствената работа в рамките на основните и допълнителните форми на работа. Постига очакваните резултати. Оценява и диагностицира, за да измери постигнат резултат. Дава обратна връзка и насока за подобрение. Използва индивидуален подход. Справя се с проблеми в работата с деца със СОП, с обучителни трудности, от уязвими общности и др. Бързо се ориентира в конкретна ситуация и допринася за успешно решение. Ефективно прилага иновативни и интерактивни методи на обучение, ориентирани към напредъка на всяко дете/ученик. Умее да мотивира децата/учениците за работа в екип. Оказва методическа и организационна подкрепа.
Организационна компетентност
1,0 точка: Не участва в разработването и изпълнението на стратегията на институцията. Трудно работи с колегите; не изразява готовност да взаимодейства открито и да сътрудничи, ако обстоятелствата не го налагат. Има проблеми при работа в екип. Среща трудности при справянето с конфликтни ситуации и вземането на добри решения. По-скоро пасивен, работи без желание, само върху задачи, които са изрично зададени, рядко се включва в разрешаването на проблеми, свързани със собствената работа. Няма необходимата компетентност и нагласа да помага на колегите си. Среща затруднения при работа с родителите, рядко дава обратна връзка. Дейностите му често не съответстват или не са обвързани със стратегията на институцията и поставените стратегически цели. Не се включва в работа по проекти. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
1,5 точки: Поддържа коректни взаимоотношения; взаимодейства с останалите колеги, доколкото го изисква работата и когато е необходимо. Пълноценно общува с родителите. Проявява инициативност в работата, готовност да се включва в изпълнението на нови задачи и разрешаването на проблемни ситуации. Проявява самоинициатива, предлага решения. Включва се в подкрепа на колеги при необходимост. Препоръчва се допълнителна квалификация.
2,0 точки: Активно участва в изпълнението и прави предложения за актуализирането на стратегията на институцията. Поддържа добри взаимоотношения и работи в сътрудничество с колегите и други партньори с цел изпълнение на работата. Активно взаимодейства с родителите, предлага решения и търси подкрепата им за подобряване на резултатите на децата/учениците. Насърчава както колегите си, така и родителите да дискутират, обменят идеи и да работят съвместно за разрешаването на проблеми. Отличава се с активност, дава предложения и влага усилия за подобряване процеса на работа, ангажира се с изпълнението на допълнителни задачи. Оказва методическа и организационна подкрепа.
Административна компетентност
1,0 точка: Участва след възлагане в разработването и изпълнението на стратегията на институцията. Слабо познава основните нормативни документи, които регулират системата на предучилищното и училищното образование. Слабо познава държавните образователни стандарти. Има затруднение в работата с документите на образователната институция. Не участва в работата по разработването и актуализирането на училищната документация. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
1,5 точки: Познава основните нормативни документи, които регулират системата на предучилищното и училищното образование. Познава държавните образователни стандарти. Няма трудност в работата с документите на образователната институцията и ги изготвя в срок. Участва в работни групи за разработването и актуализирането на училищната документация.
2,0 точки: Ефективно прилага основните нормативни документи, които регулират системата на предучилищното и училищното образование. Изпълнява задълженията си по приемане, водене, съхраняване, отчитане на документите, с които работи. Участва в работни групи за разработването и актуализирането на правилници, правила, планове и др. на институцията, като предлага решения за подобряване на работата. Оказва методическа и организационна подкрепа и наставничество.
Други професионални изисквания
1,0 точка: Спазва определеното работно време. Среща затруднения за изпълнението, координирането и контролирането на всички планирани задачи и дейности. В екипната работа допуска закъснения и неточност, което води до слабости в изпълнението на задачите. Подценява необходимостта от повишаване на квалификацията, не я обвързва с възможностите за развитие. Няма задължителните за атестационния период брой квалификационни кредити и задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Не използва ефективно ресурсите на средата, с които институцията разполага. Необходима е допълнителна квалификация. Необходима е методическа или организационна подкрепа.
1,5 точки: Изпълнява своите задължения. Ефективно използва работното време. Не среща трудности при справянето с възникнали проблеми и задачи. Отнася се отговорно към работата. Проявява мотивация и участва в допълнителни обучения. Има задължителните за атестационния период брой квалификационни кредити, но няма задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Положително е настроен към предложения за промяна и обогатяване на опита. Рационално използва ресурсите на институцията. Разбира и следва образователните цели на институцията. Препоръчва се допълнителна квалификация.
2,0 точки: Ефективно изпълнява своите задължения и отговорности. Отговорно, в срок, с необходимата точност и качествено изпълнява възложените задачи. Спазва вътрешните правила за работа. Изпълнява качествено и точно поставените задачи. Постига желаните цели в определените срокове. Преодолява възникнали трудности и информира за крайния резултат. Обогатява знанията си както чрез самоподготовка, така и чрез активното включване в организирани обучения. Има задължителните за атестационния период брой квалификационни кредити и задължителния брой часове участие във вътрешноинституционалната квалификация за всяка от годините в периода на атестиране. Ефективно използва ресурсите/базата на образователната институция, обогатява ги и търси и предлага допълнителни възможности за подобряване. Изпълнява образователната политика на институцията, като подпомага колегите си при реализиране на поставените цели. Оказва методическа и организационна подкрепа.', 42)
on conflict (code) do nothing;

